 98	int main(void) {
 99	    /* 1. Bật xung nhịp cho các cổng GPIOA, GPIOD, GPIOG, GPIOK */
100	    RCC_AHB1ENR |= (RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIODEN |
101	                    RCC_AHB1ENR_GPIOGEN | RCC_AHB1ENR_GPIOKEN);
102	
103	    /* 2. Cấu hình các chân LED thành General Purpose Output mode (01b) */
104	    /* PG6 (LED1) */
105	    GPIOG_MODER &= ~(3UL << (LED1_PIN * 2));
106	    GPIOG_MODER |=  (1UL << (LED1_PIN * 2));
107	
108	    /* PD4 (LED2), PD5 (LED3) */
109	    GPIOD_MODER &= ~((3UL << (LED2_PIN * 2)) | (3UL << (LED3_PIN * 2)));
110	    GPIOD_MODER |=  ((1UL << (LED2_PIN * 2)) | (1UL << (LED3_PIN * 2)));
111	
112	    /* PK3 (LED4) */
113	    GPIOK_MODER &= ~(3UL << (LED4_PIN * 2));
114	    GPIOK_MODER |=  (1UL << (LED4_PIN * 2));
115	
116	    /* 3. Cấu hình chân PA0 (USER BUTTON) thành Input mode (00b) */
117	    GPIOA_MODER &= ~(3UL << (BUTTON_PIN * 2));
118	    /* Theo BSP dòng 281-320: Pull = GPIO_NOPULL (00b) */
119	    GPIOA_PUPDR &= ~(3UL << (BUTTON_PIN * 2));
120	
121	    /* Ban đầu tắt tất cả các đèn LED */
122	    all_leds(0);
123	
124	    uint8_t step = 1;
125	
126	    while (1) {
127	        if (button_is_pressed()) {
128	            /*
129	             * CHẾ ĐỘ 2: Nút đang BẤM
130	             * Phản ứng đổi rõ rệt: Cả 4 đèn LED chớp nháy đồng loạt cực nhanh (khác hẳn chạy tuần tự)
131	             */
132	            all_leds(1);
133	            delay_cycles(200000);
134	            all_leds(0);
135	            delay_cycles(200000);
136	        } else {
137	            /*
138	             * CHẾ ĐỘ 1: Nút đang NHẢ (bình thường)
139	             * Chạy tuần tự vòng quanh 4 đèn (Green -> Orange -> Red -> Blue)
140	             */
141	            led_set(1, (step == 1));
142	            led_set(2, (step == 2));
143	            led_set(3, (step == 3));
144	            led_set(4, (step == 4));
145	
146	            delay_cycles(400000);
147	
148	            step++;
149	            if (step > 4) {
150	                step = 1;
151	            }
152	        }
153	    }
154	
155	    return 0;
